 const ledger={partyId:party.id,date:now,debitRial:original.kind==="RECEIPT"?amount:0,creditRial:original.kind==="PAYMENT"?amount:0,description:"برگشت وصول/پرداخت چک "+check.number,referenceId:reversalReference};
 
