 await postVoucherAtomic([["checks",check],["parties",party],["treasury",original],["treasury",reversal],["partyLedger",ledger]],{number:check.reversalVoucherNumber,date:now,description:"برگشت وصول/پرداخت چک "+check.number,reference:reversalReference},reversalLines,[{store:"checks",key:Number(check.id),expected:checkSnapshot},{store:"parties",key:Number(party.id),expected:partySnapshot},{store:"treasury",key:Number(original.id),expected:treasurySnapshot},{store:"treasuryAllocations",match:{treasuryId:Number(original.id)},expected:null},...accountGuards]);
