function validateReversalVoucherLines({voucher,lines,accounts,expectedLines=null,expectedTotal=null,label="سند"}){
 if(!voucher||!Number.isSafeInteger(Number(voucher.id))||Number(voucher.id)<=0)throw Error("سند اصلی "+label+" معتبر نیست");
 if(!Array.isArray(lines)||lines.length<2)throw Error("ردیف‌های سند اصلی "+label+" ناقص است");
 const accountCodes=new Set((accounts||[]).map(account=>String(account.id)));
 const normalize=line=>{
  const accountCode=String(line.accountCode??"").trim(),debitRial=Number(line.debitRial||0),creditRial=Number(line.creditRial||0);
  if(!accountCode||!accountCodes.has(accountCode))throw Error("کد حساب "+(accountCode||"(خالی)")+" در سند اصلی "+label+" معتبر نیست");
  if(!Number.isSafeInteger(debitRial)||debitRial<0||!Number.isSafeInteger(creditRial)||creditRial<0||((debitRial>0)===(creditRial>0)))throw Error("مبلغ یا ماهیت یکی از ردیف‌های سند اصلی "+label+" معتبر نیست");
  return {accountCode,debitRial,creditRial};
 };
 const actual=lines.map(normalize),debit=actual.reduce((sum,line)=>sum+line.debitRial,0),credit=actual.reduce((sum,line)=>sum+line.creditRial,0);
 if(!Number.isSafeInteger(debit)||!Number.isSafeInteger(credit)||debit<=0||debit!==credit)throw Error("سند اصلی "+label+" تراز یا معتبر نیست");
 if(expectedTotal!==null&&expectedTotal!==undefined&&(!Number.isSafeInteger(Number(expectedTotal))||debit!==Number(expectedTotal)))throw Error("جمع سند اصلی "+label+" با مبلغ عملیات مطابقت ندارد");
 if(expectedLines){
  const expected=expectedLines.map(normalize),signature=line=>line.accountCode+"|"+line.debitRial+"|"+line.creditRial;
  const actualSignatures=actual.map(signature).sort(),expectedSignatures=expected.map(signature).sort();
  if(actualSignatures.length!==expectedSignatures.length||actualSignatures.some((value,index)=>value!==expectedSignatures[index]))throw Error("حساب یا مبلغ یکی از ردیف‌های سند اصلی "+label+" با عملیات مرجع مطابقت ندارد");
 }
 return actual.map(line=>({accountCode:line.accountCode,debitRial:line.creditRial,creditRial:line.debitRial,description:"برگشت "+label}));
}
function applyPartyBalanceDelta(party,delta,label="طرف حساب"){
 const current=Number(party?.balance||0),change=Number(delta),next=current+change;
 if(!Number.isSafeInteger(current)||!Number.isSafeInteger(change)||!Number.isSafeInteger(next))throw Error("مانده "+label+" از محدوده عددی مجاز خارج است");
 party.balance=next;return next;
}
function sameGuardValue(a,b){
 if(Object.is(a,b))return true;
 if(a===null||b===null||typeof a!=="object"||typeof b!=="object")return false;
 if(Array.isArray(a)!==Array.isArray(b))return false;
 const aKeys=Object.keys(a),bKeys=Object.keys(b);
 return aKeys.length===bKeys.length&&aKeys.every(key=>Object.prototype.hasOwnProperty.call(b,key)&&sameGuardValue(a[key],b[key]));
}
function postVoucherAtomic(entries,voucher,lines,guards=[]){
 const stamp=globalThis.HolooOperationDate?.stampOperationRecord;
 if(!stamp)throw new Error("ماژول تاریخ عملیات بارگذاری نشده است");
 entries=entries.map(([store,value])=>[store,stamp({store,record:value,mode:operationDateMode,manualValue:operationManualDate})]);
 voucher=stamp({store:"vouchers",record:voucher,mode:operationDateMode,manualValue:operationManualDate});
 const linkedOrder=entries.find(([store,value])=>store==="salesOrders"&&value?.status==="INVOICED");
 if(linkedOrder)guards=[...guards,{store:"salesOrders",key:Number(linkedOrder[1].id),expected:{status:"APPROVED"}}];
 return new Promise((res,rej)=>{
  const names=[...new Set([...entries.map(x=>x[0]),...guards.map(x=>x.store),"vouchers","voucherLines","auditLog"])],tx=db.transaction(names,"readwrite");
  let duplicateReference=false,staleState=false,overlappingClose=false;
  const writeEntriesAndVoucher=()=>{
   for(const [store,value] of entries)tx.objectStore(store).put(value);
   const check=tx.objectStore("vouchers").getAll();
   check.onsuccess=()=>{
    if(voucher.reference&&check.result.some(v=>v.reference===voucher.reference)){duplicateReference=true;try{tx.abort()}catch(_){}return}
    const closeMatch=/^YEAR_END_CLOSE:(\d+):(\d+)$/.exec(String(voucher.reference||""));
    if(closeMatch){
     const from=Number(closeMatch[1]),to=Number(closeMatch[2]);
     const overlap=globalThis.HolooAccountingReports?.hasOverlappingPeriodClose;
     if(!Number.isSafeInteger(from)||!Number.isSafeInteger(to)||typeof overlap!=="function"||overlap(check.result,from,to)){
      overlappingClose=true;try{tx.abort()}catch(_){}return;
     }
    }
    const request=tx.objectStore("vouchers").add(voucher);
    request.onsuccess=()=>{
     const voucherId=request.result;
     for(const line of lines)tx.objectStore("voucherLines").add({...line,voucherId});
     tx.objectStore("auditLog").add({action:"ثبت سند مالی",store:"vouchers",recordId:voucherId,at:Date.now(),summary:voucher.description||voucher.number});
    };
    request.onerror=()=>{try{tx.abort()}catch(_){}};
   };
   check.onerror=()=>{try{tx.abort()}catch(_){}};
  };
  const validateGuards=()=>{
   if(!guards.length){writeEntriesAndVoucher();return}
   let completed=0,failed=false;
   guards.forEach(guard=>{
    const store=tx.objectStore(guard.store),request=guard.match?store.getAll():store.get(guard.key);
    request.onsuccess=()=>{
     if(failed)return;
     const current=guard.match?request.result.find(row=>Object.entries(guard.match).every(([key,value])=>String(row[key])===String(value))):request.result;
     const valid=guard.expected===null?current===undefined:!!current&&Object.entries(guard.expected||{}).every(([key,value])=>sameGuardValue(current[key],value));
     if(!valid){failed=true;staleState=true;try{tx.abort()}catch(_){};return}
     completed++;if(completed===guards.length)writeEntriesAndVoucher();
    };
    request.onerror=()=>{failed=true;try{tx.abort()}catch(_){}};
   });
  };
  validateGuards();
  tx.oncomplete=()=>res();
  tx.onerror=()=>rej(tx.error||new Error("ثبت سند حسابداری ناموفق بود"));
  tx.onabort=()=>rej(staleState?new Error("اطلاعات انبار یا سند هم‌زمان در زبانه دیگری تغییر کرده است؛ صفحه را تازه‌سازی و عملیات را دوباره بررسی کنید"):duplicateReference?new Error("سندی با این شناسه مرجع قبلاً ثبت شده است"):overlappingClose?new Error("این بازه با یک دوره مالی بسته‌شده هم‌پوشانی دارد؛ ثبت سند انجام نشد"):tx.error||new Error("ثبت عملیات لغو شد"));
 });
}
async function createPartyWithOpeningBalance(record,plan){
 const stamp=globalThis.HolooOperationDate?.stampOperationRecord;
 if(typeof stamp!=="function")throw new Error("ماژول تاریخ عملیات بارگذاری نشده است");
 const now=Date.now(),mode=operationDateMode,manualValue=operationManualDate;
 return new Promise((resolve,reject)=>{
  const tx=db.transaction(["parties","partyLedger","vouchers","voucherLines","auditLog"],"readwrite");
  let partyId=null;
  const partyRecord=stamp({store:"parties",record:{...record},mode,manualValue});
  const addParty=tx.objectStore("parties").add(partyRecord);
  addParty.onsuccess=()=>{
   partyId=addParty.result;
   const movement=stamp({store:"partyLedger",record:{partyId,date:now,debitRial:plan.debitRial,creditRial:plan.creditRial,description:"مانده افتتاحیه",referenceId:"OPENING:PARTY:"+partyId},mode,manualValue});
   tx.objectStore("partyLedger").add(movement);
   const voucher=stamp({store:"vouchers",record:{number:"OPEN-"+partyId+"-"+now,date:now,description:"مانده افتتاحیه "+record.name,reference:"OPENING:PARTY:"+partyId},mode,manualValue});
   const addVoucher=tx.objectStore("vouchers").add(voucher);
   addVoucher.onsuccess=()=>{
    for(const line of plan.journal)tx.objectStore("voucherLines").add({...line,voucherId:addVoucher.result});
    tx.objectStore("auditLog").add({action:"ثبت سند مالی",store:"vouchers",recordId:addVoucher.result,at:Date.now(),summary:voucher.description});
   };
   addVoucher.onerror=()=>{try{tx.abort()}catch(_){}};
   tx.objectStore("auditLog").add({action:"ثبت طرف حساب",store:"parties",recordId:partyId,at:Date.now(),summary:"ایجاد "+record.name});
   tx.objectStore("auditLog").add({action:"ثبت مانده افتتاحیه",store:"partyLedger",recordId:partyId,at:Date.now(),summary:record.name});
  };
  addParty.onerror=()=>{try{tx.abort()}catch(_){}};
  tx.oncomplete=()=>resolve(partyId);
  tx.onerror=()=>reject(tx.error||new Error("ثبت طرف حساب و مانده افتتاحیه ناموفق بود"));
  tx.onabort=()=>reject(tx.error||new Error("ثبت طرف حساب و مانده افتتاحیه لغو شد"));
 });
}
